// Pure register renderer. The public page, scripts/render-subprocessor-register.mjs
// and the legal release (scripts/lib/legal-release.mjs) all write the register
// from the data they are given, so the generated bytes cannot drift apart.
// No JSON import here: the release passes the register from its own tree.
export const REGISTER_SOURCE = "src/data/subprocessors.json";
const REGISTER_DOCUMENT = "docs/legal/subprocessor-register-20261010.md";
export const REGISTER_POLICY_DOCUMENTS = Object.freeze([
  "docs/legal/data-policy-20261009.md",
  "docs/legal/data-policy-20261009-es.md",
]);
export const REGISTER_START = "<!-- BEGIN GENERATED SUBPROCESSORS -->";
export const REGISTER_END = "<!-- END GENERATED SUBPROCESSORS -->";
const HEADER = "<!-- Generated by node scripts/render-subprocessor-register.mjs. Edit src/data/subprocessors.json. -->\n\n";

function historyLine(event, lang, copy) {
  if (event.kind === "baseline") return copy.baseline;
  if (event.kind === "amendment") {
    const before = event.previous[lang]?.scope ?? event.previous.en.scope;
    return `${copy.amended}: ${event.summary[lang] ?? event.summary.en} ${copy.previousScope}: ${before}`;
  }
  return `${copy.starts}: ${event.starts}.`;
}

export function renderRegisterMarkdownFrom(register, lang) {
  const copy = register.copy[lang];
  const rows = register.providers.map((provider) => {
    const sources = (provider.sources || []).map((source) => `[${source[lang]}](${source.url}) (${copy.sourceRead}: ${source.read})`).join("; ");
    return `| ${provider.name} | ${provider[lang].country}${sources ? ` ${sources}` : ""} | ${provider[lang].scope} |`;
  });
  return [
    `## ${copy.title}`, "", `${copy.date}: ${register.reviewed}`, "", copy.status, "", copy.notOperative, "", copy.intro, "",
    `| ${copy.providers} | ${copy.country} | ${copy.scope} |`, "| --- | --- | --- |", ...rows, "",
    copy.pending, "", `### ${copy.internal}`, "", copy.mesh, "", copy.notice, "", copy.remedy, "", copy.refund, "",
    `### ${copy.history}`, "", ...register.history.map((event) => `- ${event.announced}: ${event.providers.join(", ")}. ${historyLine(event, lang, copy)}`),
  ].join("\n");
}

// The standalone register and the English policy carry both languages; the
// Spanish policy carries the Spanish register only.
export function registerCopies(register) {
  const both = HEADER + ["en", "es"].map((lang) => renderRegisterMarkdownFrom(register, lang)).join("\n\n---\n\n") + "\n";
  return {
    [REGISTER_DOCUMENT]: both,
    [REGISTER_POLICY_DOCUMENTS[0]]: both,
    [REGISTER_POLICY_DOCUMENTS[1]]: `${HEADER}${renderRegisterMarkdownFrom(register, "es")}\n`,
  };
}

export function spliceRegisterBlock(draft, copy, path) {
  const startIndex = draft.indexOf(REGISTER_START);
  const endIndex = draft.indexOf(REGISTER_END);
  if (startIndex < 0 || endIndex < startIndex + REGISTER_START.length
    || draft.indexOf(REGISTER_START, startIndex + REGISTER_START.length) !== -1
    || draft.indexOf(REGISTER_END, endIndex + REGISTER_END.length) !== -1) {
    throw new Error(`Expected exactly one ordered generated register boundary pair in ${path}`);
  }
  return `${draft.slice(0, startIndex)}${REGISTER_START}\n${copy}\n${REGISTER_END}${draft.slice(endIndex + REGISTER_END.length)}`;
}
